import {NextRequest,NextResponse} from 'next/server';
export const runtime='nodejs';
export async function GET(req:NextRequest){
  const citation=req.nextUrl.searchParams.get('citation')?.trim();
  if(!citation) return NextResponse.json({status:'UNRESOLVED',reason:'citation is required'},{status:400});
  if(citation.length>120) return NextResponse.json({status:'UNRESOLVED',reason:'citation too long'},{status:400});
  const token=process.env.COURTLISTENER_TOKEN;
  if(!token) return NextResponse.json({status:'UNRESOLVED',reason:'CourtListener is not configured'});
  const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),8000);
  try{
    const response=await fetch('https://www.courtlistener.com/api/rest/v4/citation-lookup/',{method:'POST',headers:{Authorization:`Token ${token}`,'Content-Type':'application/x-www-form-urlencoded','User-Agent':'RECALL-LexHack/1.0'},body:new URLSearchParams({text:citation}).toString(),signal:controller.signal,cache:'no-store'});
    if(!response.ok) return NextResponse.json({status:'UNRESOLVED',reason:`CourtListener returned ${response.status}`});
    const data=await response.json();
    return NextResponse.json({status:Array.isArray(data)&&data.length?'RESOLVED':'UNRESOLVED',source:'CourtListener citation lookup',checkedAt:new Date().toISOString(),results:data});
  }catch{return NextResponse.json({status:'UNRESOLVED',reason:'CourtListener could not be reached'});}finally{clearTimeout(timer);}
}

import {NextRequest,NextResponse} from 'next/server';
// @ts-ignore Shared incident engine is exercised in Node tests.
import {traceIncidentDependencies} from '../../../../lib/incident-trace.mjs';

export const runtime='nodejs';
export const dynamic='force-dynamic';
export const maxDuration=60;

export async function POST(req:NextRequest){
  try{
    const body=await req.json();
    const dependencies=Array.isArray(body?.dependencies)?body.dependencies.slice(0,10):[];
    if(!dependencies.length)return NextResponse.json({ok:false,state:'INVALID_INPUT',message:'At least one incident dependency is required.'},{status:400});
    const safe=dependencies.map((item:any,index:number)=>({
      id:String(item?.id||`dependency-${index+1}`).slice(0,120),
      dependencyType:['AUTHORITY','QUOTATION','PROPOSITION'].includes(String(item?.dependencyType))?String(item.dependencyType):'AUTHORITY',
      rawText:String(item?.rawText||'').slice(0,600),
      canonicalCitation:item?.canonicalCitation?String(item.canonicalCitation).slice(0,220):undefined,
      quotation:item?.quotation?String(item.quotation).slice(0,1200):undefined
    })).filter((item:any)=>item.rawText||item.canonicalCitation||item.quotation);
    if(!safe.length)return NextResponse.json({ok:false,state:'INVALID_INPUT',message:'No traceable incident dependencies were supplied.'},{status:400});

    const token=process.env.COURTLISTENER_TOKEN;
    if(!token)return NextResponse.json({ok:false,state:'AUTH_REQUIRED',message:'Live CourtListener search is not configured on this deployment.'},{status:503});
    const result=await traceIncidentDependencies(safe,token,{maxCandidatesPerDependency:Math.max(1,Math.min(Number(body?.maxCandidatesPerDependency)||10,20))});
    const rateLimited=result.statuses.find((status:any)=>status.state==='rate_limited');
    const headers:Record<string,string>={};
    if(rateLimited?.retryAfterMs)headers['Retry-After']=String(Math.max(1,Math.ceil(rateLimited.retryAfterMs/1000)));
    return NextResponse.json(result,{status:rateLimited?429:200,headers});
  }catch{
    return NextResponse.json({ok:false,state:'SOURCE_ERROR',message:'The incident trace could not be completed.'},{status:500});
  }
}

import {NextRequest,NextResponse} from 'next/server';
// @ts-ignore Shared JS engine is also exercised directly by Node benchmark tests.
import {traceCourtListener} from '../../../lib/courtlistener.mjs';

export const runtime='nodejs';
export const dynamic='force-dynamic';
export const maxDuration=60;

export async function POST(req:NextRequest){
  try{
    const body=await req.json();
    const input=String(body?.input||'').trim();
    const quote=String(body?.quote||'').trim();
    if(input.length>400||quote.length>1200)return NextResponse.json({ok:false,state:'INVALID_INPUT',message:'Input exceeds prototype limits.'},{status:400});
    if(!input&&!quote)return NextResponse.json({ok:false,state:'INVALID_INPUT',message:'Enter a citation, case citation, or quotation.'},{status:400});

    const token=process.env.COURTLISTENER_TOKEN;
    if(!token)return NextResponse.json({ok:false,state:'AUTH_REQUIRED',message:'Live CourtListener search is not configured on this deployment.',recordedDemoAvailable:true},{status:503});

    const maxCandidates=Math.max(1,Math.min(Number(body?.maxCandidates)||25,50));
    const broad=body?.broad===true;
    const result=await traceCourtListener({input,quote,maxCandidates,broad,signal:req.signal},token);
    const status=result.ok?200:result.state==='AUTH_ERROR'?502:result.state==='RATE_LIMITED'?429:result.state==='INVALID_INPUT'?400:503;
    const headers:Record<string,string>={};
    if(result.retryAfterMs)headers['Retry-After']=String(Math.max(1,Math.ceil(result.retryAfterMs/1000)));
    if(result.diagnostics?.traceId)headers['X-Recall-Trace-Id']=String(result.diagnostics.traceId);
    return NextResponse.json(result,{status,headers});
  }catch{
    return NextResponse.json({ok:false,state:'SOURCE_ERROR',message:'The public-source trace could not be completed.'},{status:500});
  }
}

