.fc-scene[data-theme="light"] .fc-setting-row{border-color:#d8d7d1}
.fc-scene[data-theme="light"] .fc-setting-row button{background:#ecebe7;border-color:#d2d1cb;color:#676962}
.fc-scene[data-theme="light"] .fc-setting-row button.is-selected{background:#deddd8;color:#181916;border-color:#aaa}
.fc-scene[data-theme="light"] .fc-theme-switch button.is-selected{background:#d8d7d1;border-color:#aaa}
.fc-scene[data-theme="light"] .fc-time-grid i,
.fc-scene[data-theme="light"] .fc-dot-guides i,
.fc-scene[data-theme="light"] .fc-stream-guides i{border-color:#dfded8}
.fc-scene[data-theme="light"] .fc-event{background:linear-gradient(90deg,rgba(231,230,224,.96),rgba(231,230,224,.72))}
.fc-scene[data-theme="light"] .fc-dot{background:#d7d6d0}
.fc-scene[data-theme="light"] .fc-dot.is-hot{background:var(--fc-orange)}
.fc-scene[data-theme="light"] .fc-builder-row,
.fc-scene[data-theme="light"] .fc-workspace-list button,
.fc-scene[data-theme="light"] .fc-trace-list button,
.fc-scene[data-theme="light"] .fc-authority-list button{border-color:#deddd7}
.fc-scene[data-theme="light"] .fc-field input,
.fc-scene[data-theme="light"] .fc-trace-form input,
.fc-scene[data-theme="light"] .fc-trace-form textarea{background:#f7f6f2;color:#181916;border-color:#d4d3cd}

.fc-profile:focus-visible,.fc-theme-switch button:focus-visible,.fc-popover a:focus-visible,.fc-popover button:focus-visible{
  outline:2px solid var(--fc-orange);
  outline-offset:2px;
}

@media(max-width:980px){
  .fc-settings-popover{left:14px;top:82px;bottom:auto}
  .fc-status-popover,.fc-profile-popover{right:14px;top:82px}
}

